  Class<?> panel=cl.loadClass("com.kisa.transport.SignalPanel"),repo=cl.loadClass("com.skt.tmap.trafficlight.TrafficSignalInfoRepository");Activity a=(Activity)((java.lang.ref.Reference<?>)field(panel,"activity")).get();if(a==null)throw new Exception("Foreground Tmap navigation missing");Object state=field(repo,"d"),visible=field(repo,"b"),location=field(repo,"f");Object oldState=get(state,"getValue"),oldVisible=get(visible,"getValue"),oldLocation=get(location,"getValue");Object lamps=cl.loadClass("com.skt.tmap.trafficlight.b").getConstructor().newInstance();set(lamps,"a",true);set(lamps,"b",true);set(lamps,"f",17);Object point=cl.loadClass("com.skt.tmap.engine.navigation.route.data.MapPoint").getConstructor(double.class,double.class).newInstance(126.6981604,37.6034634);set(lamps,"g",point);JSONObject detail=new JSONObject().put("lat",37.6034634).put("lon",126.6981604).put("distance",194).put("straight","RED_LIGHT_ON").put("straight_remain_time",17).put("left","GREEN_LIGHT_ON").put("left_remain_time",8);TextView[] label={null};ImageButton[] sampleButton={null};Throwable[] failure={null};
